const incoming = $input.first().json;
const body = incoming?.body ?? incoming;
const record = body !== null && typeof body === 'object' && !Array.isArray(body);
const question = record && typeof body.question === 'string' ? body.question.trim() : '';
const language = record && ['auto','tl','en'].includes(body.language) ? body.language : 'auto';
const requestId = record && typeof body.request_id === 'string' ? body.request_id.replace(/[^a-zA-Z0-9_-]/g, '').slice(0,80) : '';
const currentDate = typeof body?.current_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(body.current_date) ? body.current_date : new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const history = body?.history ?? [];
let error = '';
if (!Array.isArray(history) || history.length > 8 || history.some(t => !t || typeof t !== 'object' || Array.isArray(t) || Object.keys(t).some(k => !['role','content'].includes(k)) || !['user','assistant'].includes(t.role) || typeof t.content !== 'string' || !t.content.trim() || t.content.length > 1000)) error = 'Invalid conversation history.';
if (!question) error = 'A question is required.';
else if (question.length > 500) error = 'Question must not exceed 500 characters.';
return [{ json: { valid: !error, error, current_date: currentDate, question, history: error ? [] : history, language, request_id: requestId || null } }];

const response = $input.first().json;
const base = $('Build Classifier Prompt').item.json;
const rawCandidate = response?.candidates?.[0]?.content?.parts?.[0]?.text;
if (response?.candidates?.[0]?.finishReason !== 'STOP' || typeof rawCandidate !== 'string' || !rawCandidate.trim()) {
  return [{ json: { success: false, error_type: 'classifier_error', error: 'The AI classifier is temporarily unavailable.', request_id: base.request_id } }];
}
let raw = String(rawCandidate).replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch {
  return [{ json: { success: false, error_type: 'classifier_error', error: 'The AI classifier returned an invalid response.', request_id: base.request_id } }];
}
if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return [{ json: { success: false, error_type: 'classifier_error', error: 'The AI classifier returned an invalid response.', request_id: base.request_id } }];
}
const intentMetrics = {
  own_profile: new Set(['full_name','designation','company_email','profile_summary']),
  own_attendance: new Set(['absence_dates','late_dates','attendance_history','absent_count','last_absent_date','late_count','present_count','leave_day_count','attendance_summary','time_in','time_out']),
  own_leave_balance: new Set(['remaining_credits','total_credits','used_credits','leave_balance_summary']),
  own_leave_history: new Set(['leave_request_count','approved_count','pending_count','rejected_count','leave_history_summary']),
  own_payslip: new Set(['basic_pay','gross_pay','net_pay','deductions','payslip_summary']),
  directory_by_designation: new Set(['company_email','directory_profile']),
  directory_lookup: new Set(['company_email','designation','directory_profile']),
  restricted_other_employee: new Set(['none']),
  clarification: new Set(['period','topic','payroll_cutoff','designation']),
  help: new Set(['none']),
  unsupported: new Set(['none'])
};
const requiredKeys = ['intent','metric','period','target_scope','target_name','language'];
if (Object.keys(parsed).some(key => ![...requiredKeys, 'resolved_question', 'date_start', 'date_end'].includes(key)) || (parsed.resolved_question !== undefined && (typeof parsed.resolved_question !== 'string' || !parsed.resolved_question.trim() || parsed.resolved_question.length > 500)) || !requiredKeys.every(key => typeof parsed[key] === 'string') ||
    !Object.prototype.hasOwnProperty.call(intentMetrics, parsed.intent) ||
    !intentMetrics[parsed.intent].has(parsed.metric) ||
    !['today','current_month','current_year','previous_month','previous_year','yesterday','custom','all_time','selected_payslip'].includes(parsed.period) ||
    !['self','other','none'].includes(parsed.target_scope) ||
    !['tl','en'].includes(parsed.language)) {
  return [{ json: { success: false, error_type: 'classifier_error', error: 'The AI classifier returned an invalid response.', request_id: base.request_id } }];
}
const validDate = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && Number.isFinite(Date.parse(v)) && new Date(v).toISOString().slice(0,10) === v;
if (parsed.period === 'custom' ? (!validDate(parsed.date_start) || !validDate(parsed.date_end) || parsed.date_start > parsed.date_end || Number(parsed.date_start.slice(0,4)) < 1900 || Number(parsed.date_end.slice(0,4)) > 2100) : (parsed.date_start !== undefined || parsed.date_end !== undefined)) return [{ json: { success: false, error_type: 'classifier_error', request_id: base.request_id } }];
if (parsed.period === 'all_time' && !(parsed.intent === 'own_attendance' && parsed.metric === 'last_absent_date')) return [{ json: { success: false, error_type: 'classifier_error', request_id: base.request_id } }];
if (parsed.intent === 'directory_by_designation' && (parsed.target_scope !== 'other' || !/^[\p{L}\p{M}][\p{L}\p{M}\p{N} ()/'&.-]{1,79}$/u.test(parsed.target_name))) return [{ json: { success: false, error_type: 'classifier_error', request_id: base.request_id } }];
let intent = Object.prototype.hasOwnProperty.call(intentMetrics, parsed.intent) ? parsed.intent : 'unsupported';
let metric = intentMetrics[intent].has(parsed.metric) ? parsed.metric : 'none';
let period = ['today','current_month','current_year','previous_month','previous_year','yesterday','custom','all_time','selected_payslip'].includes(parsed.period) ? parsed.period : 'current_month';
let targetScope = ['self','other','none'].includes(parsed.target_scope) ? parsed.target_scope : 'none';
let targetName = String(parsed.target_name ?? '').replace(/[%_*?]/g, '').replace(/[^\p{L}\p{M} .'-]/gu, '').replace(/\s+/g, ' ').trim().slice(0, 80);
if (intent === 'directory_by_designation') targetName = parsed.target_name;
const language = base.language === 'en' || base.language === 'tl' ? base.language : parsed.language;
if (intent.startsWith('own_') && (targetScope !== 'self' || parsed.target_name.trim() !== '')) { intent = targetScope === 'other' || parsed.target_name.trim() !== '' ? 'restricted_other_employee' : 'unsupported'; metric = 'none'; }
if (intent === 'directory_lookup' && (targetScope !== 'other' || targetName.length < 2 || parsed.target_name.trim() !== targetName)) { intent = 'unsupported'; metric = 'none'; targetScope = 'none'; targetName = ''; }
if (intent === 'restricted_other_employee') { metric = 'none'; targetScope = 'other'; }
if (intent !== 'own_payslip' && period === 'selected_payslip') period = 'current_month';
if (intent === 'own_payslip' && period !== 'selected_payslip') { intent = 'unsupported'; metric = 'none'; }
if (intent === 'help' || intent === 'unsupported') { metric = 'none'; targetScope = 'none'; targetName = ''; }
return [{ json: { success: true, ...(period === 'custom' ? { date_start: parsed.date_start, date_end: parsed.date_end } : {}), intent, metric, period, target_scope: targetScope, target_name: targetName, language, ...(typeof parsed.resolved_question === 'string' ? { resolved_question: parsed.resolved_question } : {}), request_id: base.request_id } }];
